    const stick=shell.querySelector('#snowStick'),nub=stick.firstElementChild;let pointerId=null;const drag=e=>{const b=stick.getBoundingClientRect(),dx=(e.clientX-b.left-b.width/2)/42,dy=(e.clientY-b.top-b.height/2)/42,n=Math.max(1,Math.hypot(dx,dy));r.stick={x:dx/n,y:dy/n};nub.style.transform=`translate(${r.stick.x*30}px,${r.stick.y*30}px)`;};stick.onpointerdown=e=>{pointerId=e.pointerId;stick.setPointerCapture(pointerId);drag(e);};stick.onpointermove=e=>{if(e.pointerId===pointerId)drag(e);};const release=()=>{pointerId=null;r.stick={x:0,y:0};nub.style.transform='';};stick.onpointerup=stick.onpointercancel=stick.onlostpointercapture=release;
